    distributionTip:  'Способ генерации случайных отклонений. Гауссово (по умолчанию): значение выше — это СКО / стандартное отклонение σ; хвосты не ограничены, поэтому ~32% выборок его превышают. Равномерное: значение — ЖЁСТКАЯ ±граница, все отклонения внутри полосы равновероятны (СКО = граница/√3). Усечённое: значение — ЖЁСТКАЯ ±граница = 3σ, колоколообразная форма, обрезанная так, что ни одна выборка её не превышает (СКО ≈ граница/3).',
    sigmaNoteGaussian:  'σ — это одно стандартное отклонение: около 68% отклонений слоёв укладываются в ±σ, а ~32% его превышают (хвосты Гаусса не ограничены). Ошибка толщины слоя = σ abs + σ rel·d.',
    sigmaNoteUniform:   'Введённое значение трактуется как жёсткая ±граница B (наибольшее возможное отклонение), а НЕ как σ: отклонения распределены равномерно на [−B, +B], поэтому ни одно не превышает B, а фактическое СКО (эффективная σ) = B/√3 ≈ 0.58·B.',
    sigmaNoteTruncated: 'Введённое значение трактуется как жёсткая ±граница B = 3σ (т.е. σ = B/3), а НЕ как σ напрямую: гауссов колокол, обрезанный так, что ни одно отклонение не превышает ±B; фактическое СКО ≈ B/3.',
    rmsAbsTip:          'Стандартное отклонение абсолютной ошибки толщины (nm). Точный смысл зависит от выбранного распределения; для Гаусса ~68% слоёв укладываются в ±это значение.',
    rmsRelTip:          'Относительная ошибка толщины (% от толщины слоя d), добавляется к σ abs. Точный смысл зависит от выбранного распределения; для Гаусса ~68% слоёв укладываются в ±это значение.',
    rmsReNTip:          'Ошибка действительной части показателя преломления n. Точный смысл зависит от выбранного распределения; для Гаусса ~68% слоёв укладываются в ±это значение.',
    rmsImNTip:          'Ошибка мнимой части показателя преломления k (поглощение). Точный смысл зависит от выбранного распределения; для Гаусса ~68% слоёв укладываются в ±это значение.',
    envelope:           'min/max',
    envelopeTip:        'Показать огибающую реализованных min/max (крайние спектры по всем испытаниям). Для Uniform/Truncated это истинная жёсткая граница; для Гаусса предела нет — огибающая расширяется с числом испытаний.',
    corridorTip:        'Заштрихованная полоса = среднее ± k·σ спектра по испытаниям (k ниже). Только отображение — изменение k перерисовывает полосу без перезапуска Монте-Карло и не влияет на выход. k≈1 ≈ 68% только для Гаусса.',
    specYield:        'Выход по спец.',
    specYieldTip:     'Оценивать Спецификацию (квалификаторы) в каждом испытании Монте-Карло и показывать выход процесса — % испытаний, где все требования выполнены. Оценивается на возмущённой по толщине конструкции.',
