    sigmaNoteUniform: '您输入的值被当作硬 ±界 B（最大可能偏差），而非 σ：偏差均匀分布在 [−B, +B] 上，因此没有偏差超出 B，实际 RMS（有效 σ）= B/√3 ≈ 0.58·B。',
    sigmaNoteTruncated: '您输入的值被当作硬 ±界 B = 3σ（因此 σ = B/3），而非直接作为 σ：高斯钟形被裁剪使任何偏差不超出 ±B；实际 RMS ≈ B/3。',
